// Notions fines (13.11) : le catalogue suit les référentiels compétence par compétence (≈ une notion pour
// 2 à 4 compétences), au lieu d'une notion par chapitre. Chargé après gen2.js.
// Chaque entrée : id, thème, libellé, exemple, CH [année], again, MP, codes (motif des compétences du
// référentiel testées), indice, leçon [titre, intro, règle, exemples, piège], g = [niveau 1, niveau 2, niveau 3].

const FINE = [];
const fx = (v, k = 6) => +(+v).toFixed(k);
const QV = (q, value, sol, o = {}) => Object.assign({ q, spec: Object.assign({ kind: "value", value }, o.round ? { round: o.round } : {}, o.plain ? { plain: true } : {}), sol }, o.fig ? { fig: o.fig } : {});
const QX = (q, expr, sol, o = {}) => Object.assign({ q, spec: Object.assign({ kind: "expr", expr }, o.form ? { form: o.form } : {}), sol }, o.fig ? { fig: o.fig } : {});
const tu = (u) => "\\ \\text{" + u.replace(/([a-zA-Z]+)\^(\d)/, "$1}^$2\\text{") + "}";
const pickN = (arr, n) => shuffle(arr.slice()).slice(0, n);
const lst = (a) => a.map((v) => M(typeof v === "number" ? dec(v) : v)).join(" ; ");
const divisors = (n) => { const r = []; for (let i = 1; i <= n; i++) if (n % i === 0) r.push(i); return r; };
const isPrime = (n) => { if (n < 2) return false; for (let i = 2; i * i <= n; i++) if (n % i === 0) return false; return true; };
const hm = (m) => Math.floor(m / 60) + " h " + (m % 60 < 10 ? "0" : "") + (m % 60);

