// ======================= Enregistrement =======================
// Notions remplacées par des notions plus fines (retirées du catalogue et des générateurs).
const FINE_REMOVED = ["decim", "unites", "aires"];
// Notions conservées mais recadrées (libellé, année) : [id, changements].
const FINE_PATCH = {
  arith: { label: "PGDC et PPMC" },
  rel: { label: "Nombres relatifs : multiplier, diviser, priorités", CH: [10], again: [11] },
  fracadd: { label: "Fractions : additionner, soustraire" },
  prop: { label: "Quatrième proportionnelle, règle de trois" },
  valnum: { label: "Substituer dans une expression littérale" },
  angtri: { label: "Somme des angles d'un triangle" },
  diagr: { label: "Diagrammes et moyennes" },
  vol: { label: "Volumes : prisme droit et cylindre", CH: [10], again: [11] },
};
(function registerFine() {
  for (const id of FINE_REMOVED) {
    const i = NOTIONS.findIndex((n) => n.id === id);
    if (i >= 0) NOTIONS.splice(i, 1);
    delete GEN[id]; delete HINTS_EXTRA[id]; delete LESSONS_EXTRA[id];
    if (typeof PROB !== "undefined") delete PROB[id];
    if (typeof PROB_EXTRA !== "undefined") delete PROB_EXTRA[id];
  }
  for (const [id, ch] of Object.entries(FINE_PATCH)) { const n = NOTIONS.find((x) => x.id === id); if (n) Object.assign(n, ch); }
  for (const f of FINE) {
    const n = { id: f.id, theme: f.theme, label: f.label, ex: f.ex, CH: f.CH, FR: null };
    if (f.again) n.again = f.again;
    if (f.MP !== undefined) n.MP = f.MP;
    // rangée après la dernière notion de la même année (ordre d'affichage)
    let at = -1; NOTIONS.forEach((x, i) => { if (x.CH && f.CH && x.CH[0] <= f.CH[0]) at = i; });
    NOTIONS.splice(at + 1, 0, n);
    GEN[f.id] = (d) => f.g[Math.min(d, f.g.length) - 1]();
    HINTS_EXTRA[f.id] = f.hint;
    LESSONS_EXTRA[f.id] = f.lesson;
  }
})();
